cssReferencia:
.componente { color: var(--texto); background: var(--superficie); border: var(--borda-espessura) var(--borda-estilo) var(--borda-cor); border-radius: var(--raio); padding: var(--espaco); box-shadow: var(--sombra); font: var(--peso-corpo) var(--escala-base)/var(--entrelinha) var(--fonte); }
.acao { min-height: var(--altura-controle); color: var(--sobre-primaria); background: var(--primaria); transition: transform var(--transicao) var(--easing), box-shadow var(--transicao) var(--easing); }
.acao:hover:not(:disabled) { transform: translateY(var(--deslocamento-hover)); box-shadow: var(--sombra-hover); }
.acao:active:not(:disabled) { transform: translateY(1px); }
:focus-visible { outline: var(--foco-espessura) solid var(--primaria); outline-offset: 3px; }
:disabled, [aria-disabled="true"] { opacity: .55; cursor: not-allowed; }
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { animation-duration: .01ms !important; transition-duration: .01ms !important; scroll-behavior: auto !important; } }
